package com.fuelflex.platform.reception.repository; import java.math.BigDecimal; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import com.fuelflex.platform.reception.entity.ReceptionItem; public interface ReceptionItemRepository extends JpaRepository<ReceptionItem,UUID>{ @Query("select coalesce(sum(i.receivedQuantity),0) from ReceptionItem i where i.purchaseOrderItem.id=:poi and i.reception.status='VALIDATED'") BigDecimal sumValidatedForPurchaseOrderItem(@Param("poi")UUID poi); List<ReceptionItem> findByReceptionId(UUID receptionId); }
